import {initLocale,language,translate,canonicalQuery,canonicalReport} from './locale.mjs';
await initLocale();
import {STATUS,clone,uid,safeUrl,parseReport,validateDataset,planImport,applyImport,matchingFeatures} from './core.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='agent-atlas.dataset.v1',UNDO='agent-atlas.undo.v1',VIEWKEY='agent-atlas.view.v1';
const names={compare:'能力对比',products:'产品档案',sources:'证据与来源',method:'评估方法',fields:'字段管理',import:'报告导入',history:'变更记录'};
let seed,data,local=false,storageIssue='',selected=['chatgpt','claude','gemini','copilot'],view='compare',moduleId='all',query='',status='all',diff=false,compact=false,importState=null,detailState=null;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function historyEntry(action,description){return {id:uid('change'),at:new Date().toISOString(),action,description}}
function save(next,action,description,addHistory=true){validateDataset(next);if(addHistory)next.history.unshift(historyEntry(action,description));next.updatedAt=new Date().toISOString().slice(0,10);try{localStorage.setItem(UNDO,JSON.stringify(data));localStorage.setItem(KEY,JSON.stringify(next));storageIssue=''}catch(e){toast('浏览器存储失败，未应用修改。请导出数据或检查空间。');return false}data=next;local=true;return true}
function download(filename,content,type='application/json'){let url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportData(){download('agent-atlas-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(data,null,2));toast('完整数据已导出；可通过报告导入恢复')}
function reportTemplate(){download('product-report-template.json',JSON.stringify({productId:'qwenwork',capabilities:[{module:'认知与知识',feature:'联网与深度研究',status:'有',summary:'请填写能力简介',detail:'请记录版本、客户端、适用范围和限制。',sourceUrl:'https://docs.qwenwork.ai/faq',sourceTitle:'QwenWork 官方 FAQ',checkedAt:'2026-10-23'}]},null,2))}
function csvExport(){let fields=localizedFeatures(selected);let out=[['模块','功能','功能定义',...selected.map(id=>data.products.find(p=>p.id===id).name)],...fields.map(f=>[data.modules.find(m=>m.id===f.moduleId).name,f.name,f.description,...selected.map(id=>{let c=data.capabilities[id][f.id];return STATUS[c.status]+' | '+c.summary})])];let q=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';download('agent-atlas-comparison.csv','\uFEFF'+out.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function logo(p){return `<span class="product-logo" style="background:${/^#[0-9a-f]{6}$/i.test(p.color)?p.color:'#567363'}">${esc(p.icon||p.name[0])}</span>`}
function badge(c){return `<span class="status ${esc(c.status)}">${STATUS[c.status]}</span>`}
function coverage(p){let cs=Object.values(data.capabilities[p.id]);return Math.round(cs.filter(c=>c.status!=='unknown').length/cs.length*100)}
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">AGENT INTELLIGENCE / ENTERPRISE IT</div><h1>${title}</h1><p class="sub">${sub}</p></div>${actions?'<div class="head-actions">'+actions+'</div>':''}</div>`}
function localizedFeatures(ids){let q=canonicalQuery(query,data);if(typeof q==='string')return matchingFeatures(data,ids,q,moduleId,status,diff);let fields=matchingFeatures(data,ids,'',moduleId,status,diff);return fields.filter(f=>[f.name,f.description,data.modules.find(m=>m.id===f.moduleId)?.name,...ids.flatMap(id=>{let c=data.capabilities[id][f.id];return [c.summary,c.detail]})].some(s=>q.matches.includes(s)));}
function selectedProducts(){return data.products.filter(p=>selected.includes(p.id))}
function switchView(v){if(!names[v])v='compare';view=v;location.hash=v;render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){document.querySelectorAll('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent=names[view];let fn={compare:renderCompare,products:renderProducts,sources:renderSources,method:renderMethod,fields:renderFields,import:renderImport,history:renderHistory};$('#app').innerHTML=(storageIssue?`<div class="section-note warning">${esc(storageIssue)}</div>`:'')+fn[view]();if(view==='compare')renderMatrix();if(view==='import')bindImport();}
function renderCompare(){let cells=selected.flatMap(id=>Object.values(data.capabilities[id]));let known=cells.filter(c=>c.status!=='unknown').length;return head('企业 AI 能力对比<span class="beta">RESEARCH BOARD</span>','选择产品，逐项比较能力、适用范围与实现方式。每一条结论，都能找到依据。',`<button class="btn" data-action="to-fields">☷ 管理字段</button><button class="btn primary" data-action="to-import">↥ 导入分析报告</button>`)+`<div class="metric-row"><div class="metric panel"><div><span>对比产品</span><b>${selected.length}<small>/ ${data.products.length} 个产品</small></b></div><div class="metric-icon">◫</div></div><div class="metric panel"><div><span>能力字段</span><b>${data.features.length}<small>覆盖 ${data.modules.length} 个模块</small></b></div><div class="metric-icon">▥</div></div><div class="metric panel"><div><span>当前产品文档结论覆盖</span><b>${cells.length?Math.round(known/cells.length*100):0}<small>% · ${known}/${cells.length} 项</small></b></div><div class="metric-icon">◇</div></div><div class="metric panel"><div><span>最近数据更新</span><b style="font-size:21px">${esc(data.updatedAt.slice(5).replace('-','.'))}<small>${local?'本地草稿':'初始基线'}</small></b></div><div class="metric-icon">◷</div></div></div><section class="selection panel"><div class="panel-title"><b>选择对比产品</b><small>点击卡片切换 · 支持任意组合</small><div class="right"><button class="link-btn" data-action="all">全部选择</button><button class="link-btn" data-action="clear">清空</button></div></div><div class="product-list">${data.products.map(p=>`<button class="product-picker ${selected.includes(p.id)?'active':''}" data-select="${esc(p.id)}" aria-pressed="${selected.includes(p.id)}"><span class="tick">✓</span>${logo(p)}<strong>${esc(p.name)}</strong><small title="${esc(p.edition)}">${esc(p.edition)}</small></button>`).join('')}</div><div class="preset-row"><span>快捷组合</span><button class="preset" data-preset="office">办公与知识工作</button><button class="preset" data-preset="coding">代码与研发</button><button class="preset" data-preset="global">全球通用助手</button><span class="local-state" style="margin-left:auto">已选 ${selected.length} 个</span></div></section><div class="hint-bar"><span>ⓘ</span><span><b>对比口径</b>　企业版产品；“有 · 条件”表示需特定客户端、配置或附加授权。“待核实”不等于“无”。</span><span class="right">点击单元格查看证据 ↗</span></div><section class="panel matrix-panel"><div class="matrix-tabs"><button data-module="all" class="${moduleId==='all'?'active':''}">全部能力<small>${data.features.length}</small></button>${data.modules.map(m=>`<button data-module="${esc(m.id)}" class="${m.id===moduleId?'active':''}">${esc(m.name)}<small>${data.features.filter(f=>f.moduleId===m.id).length}</small></button>`).join('')}</div><div class="tools"><div class="search-box"><span>⌕</span><input id="cap-search" aria-label="搜索功能与能力简介" value="${esc(query)}" placeholder="搜索功能、能力简介或关键词…"></div><select id="status-filter" aria-label="筛选支持状态"><option value="all">全部状态</option>${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${status===k?'selected':''}>${v}</option>`).join('')}</select><label class="toggle"><input id="diff-toggle" type="checkbox" ${diff?'checked':''}>只看差异</label><div class="tool-right"><label class="toggle"><input id="compact-toggle" type="checkbox" ${compact?'checked':''}>紧凑模式</label><button class="link-btn" data-action="csv">↓ 导出当前对比</button></div></div><div class="legend"><span><i></i>有</span><span class="partial"><i></i>有 · 条件</span><span class="no"><i></i>无</span><span class="unknown"><i></i>待核实</span><span style="margin-left:auto">状态与简介任一不同即为差异 · 非性能排名</span></div><div id="matrix-content"></div></section><div class="bottom-grid"><div class="panel bottom-card"><div class="box-icon">☷</div><div><h3>让对比维度跟上你的研究</h3><p>新增模块、维护功能定义与优先级；更新后的字段会同步出现在全部产品中。</p><button class="link-btn" data-action="to-fields">进入字段管理 →</button></div></div><div class="panel bottom-card"><div class="box-icon">↥</div><div><h3>把独立研究沉淀为看板数据</h3><p>导入结构化报告、匹配功能字段并预览更新。PDF / Word 的 AI 解析接口已预留。</p><button class="link-btn" data-action="to-import">导入产品报告 →</button></div></div></div>`}
function renderMatrix(){document.body.classList.toggle('compact',compact);let target=$('#matrix-content');let ps=selectedProducts();if(!ps.length){target.innerHTML='<div class="empty"><b>先选择要比较的产品</b><p>点击上方卡片，可比较任意一个或多个产品。</p><button class="btn" data-action="all">选择全部产品</button></div>';return}let fs=localizedFeatures(ps.map(p=>p.id));if(!fs.length){target.innerHTML='<div class="empty"><b>没有符合条件的能力</b><p>尝试清除搜索，切换模块或关闭“只看差异”。</p><button class="btn" data-action="reset-filters">清除筛选</button></div>';return}let mods=data.modules.filter(m=>fs.some(f=>f.moduleId===m.id));target.innerHTML=`<div class="table-scroll"><table class="matrix" style="min-width:${240+ps.length*240}px"><colgroup><col>${ps.map(()=>'<col>').join('')}</colgroup><thead><tr><th>能力模块 / 功能详情<br><span class="mini">点击产品名查看完整档案</span></th>${ps.map(p=>`<th><button data-product="${esc(p.id)}">${logo(p)}<b>${esc(p.name)}</b><span class="open">↗</span><small>${esc(p.edition)}</small></button></th>`).join('')}</tr></thead><tbody>${mods.map(m=>`<tr class="module-row"><td><span class="module-number">${String(data.modules.indexOf(m)+1).padStart(2,'0')}</span>${esc(m.name)}</td><td colspan="${ps.length}">${fs.filter(f=>f.moduleId===m.id).length} 项能力</td></tr>${fs.filter(f=>f.moduleId===m.id).map(f=>`<tr><td><span class="feature-name">${esc(f.name)}</span><span class="feature-desc">${esc(f.description)}</span><span class="feature-priority">${esc(f.priority||'P1')}</span></td>${ps.map(p=>{let c=data.capabilities[p.id][f.id];return `<td><button class="cell" data-cell="${esc(p.id)}|${esc(f.id)}" title="查看 ${esc(p.name)} · ${esc(f.name)} 详情">${badge(c)}<p>${esc(c.summary)}</p>${c.evidence?.includes('导入')?'<span class="cell-origin">导入报告 · 未独立核验</span>':''}</button></td>`}).join('')}</tr>`).join('')}`).join('')}</tbody></table></div><div class="matrix-footer"><span>显示 ${fs.length} / ${data.features.length} 项能力 · ${ps.length} 个产品　${diff?'· 差异视图':''}</span><span>${local?'当前浏览器草稿 · 可导出保存':'初始数据 · 仅文档核验'}　⇆ 横向滚动查看全部产品</span></div>`}
function renderProducts(){return head('产品档案','了解每个产品的定位、企业版边界与已记录能力。')+`<div class="section-note">范围说明：ChatGPT 与 Codex 分列；Claude 纳入其企业版 Chat / Cowork / Code。Gemini 与 Copilot 的附加组件在对应能力中标注，避免跨产品族能力混算。</div><div class="product-grid">${data.products.map(p=>`<article class="panel product-card"><span class="category">${esc(p.vendor)}</span>${logo(p)}<h2>${esc(p.name)}</h2><div class="edition">${esc(p.edition)}</div><p>${esc(p.intro)}</p><div class="coverage"><div class="track"><i style="width:${coverage(p)}%"></i></div><span>文档结论覆盖 ${coverage(p)}%</span></div><div class="card-actions"><button class="btn" data-product="${esc(p.id)}">能力详情 ↗</button><button class="link-btn" data-select="${esc(p.id)}">${selected.includes(p.id)?'✓ 已加入对比':'＋ 加入对比'}</button></div></article>`).join('')}</div>`}
function renderSources(){let ids=new Set(selected.flatMap(id=>Object.values(data.capabilities[id]).flatMap(c=>c.sourceIds)));return head('证据与来源','官方资料是初筛依据。购买前仍需验证 SKU、地区、管理员配置和合同条款。')+`<div class="section-note">初始资料核验日期：2026-10-23。导入报告的引用保留原始出处，但未自动视为已核验。覆盖率仅表示有文档结论的比例，不表示功能完整度或产品质量。</div><div class="panel simple-scroll"><table class="simple-table"><thead><tr><th>资料名称</th><th>来源</th><th>引用能力数</th><th>记录日期</th><th>当前对比</th></tr></thead><tbody>${Object.entries(data.sources).map(([id,s])=>`<tr><td><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></td><td class="source-domain">${esc(new URL(s.url).hostname)}</td><td>${Object.values(data.capabilities).flatMap(cs=>Object.values(cs)).filter(c=>c.sourceIds.includes(id)).length}</td><td class="muted">${esc(s.checkedAt||'未注明')}</td><td>${ids.has(id)?'<span class="tag">已选产品引用</span>':'—'}</td></tr>`).join('')}</tbody></table></div>`}
function renderMethod(){return head('评估方法','沿用企业 IT 的研究框架：先定义范围与准入，再验证质量与成本。',`<a class="btn" href="framework.html" target="_blank" rel="noopener">完整研究框架 ↗</a>`)+`<div class="method-grid"><article class="panel method-card"><h3>01 / 状态口径</h3><p><b>有：</b>官方资料确认存在此能力。<br><b>有 · 条件：</b>依赖客户端、附加产品、配置或授权。<br><b>无：</b>官方明确说明在限定范围内不支持。<br><b>待核实：</b>没有足够证据，或尚未完成测试。</p><p>功能存在不等于质量可靠；“支持”也不等于已包含在当前合同中。</p></article><article class="panel method-card"><h3>02 / 比较边界</h3><p>每条能力绑定产品与企业版本。记录客户端、服务地区和前置条件。模型能力、API 平台能力与用户端产品功能分开核验。</p><p>“差异”依据状态或简介差异筛选，包含实现方式差异，不代表优劣。未知项单列，不能直接按零分计入排名。</p></article><article class="panel method-card"><h3>03 / 企业准入与 PoC</h3><ul><li>确认身份、权限、数据流、日志、保留与退出能力。</li><li>用同一组真实业务任务测试，保留输入与执行轨迹。</li><li>统计端到端成功率、人工接管率、P95 延迟。</li><li>统一口径比较每成功任务成本，计入失败重试。</li></ul></article><article class="panel method-card"><h3>04 / 建议评分与 TCO</h3><p>准入通过后参考：任务效果 25%、安全 25%、集成运维 20%、规格性能 15%、TCO 10%、支持 5%。权重应由业务与 IT 共同确认。</p><p>TCO 包括订阅、模型 / 工具、集成、运维、人工审核及迁移成本。本看板未生成未经实测的产品得分或总排名。</p></article></div><div class="section-note" style="margin-top:20px">本页支持本地草稿管理；跨设备多人协作、持久服务端数据与 AI 文档抽取尚未接入。已预留版本化数据结构及解析器接口，参见报告导入中的“后续接入”。</div>`}
function renderFields(){return head('字段管理','模块与功能定义独立于产品数据维护。修改只保存在当前浏览器，可通过完整数据导出迁移。',`<button class="btn" data-action="add-module">＋ 新增模块</button><button class="btn primary" data-action="add-feature">＋ 新增功能字段</button>`)+`<div class="section-note">字段使用稳定 ID。重命名和移动功能会保留已有产品结论；新增字段会为所有产品初始化“待核实”。删除时同步移除对应能力，可在变更记录撤销最近一次修改。</div><div class="module-cards">${data.modules.map(m=>`<div class="panel module-card"><div class="flex between"><h3>${esc(m.name)}</h3><span class="tag">${data.features.filter(f=>f.moduleId===m.id).length} 字段</span></div><p>module_id: ${esc(m.id)}</p><div class="flex"><button class="link-btn" data-edit-module="${esc(m.id)}">编辑模块</button><button class="link-btn" data-delete-module="${esc(m.id)}">删除</button></div></div>`).join('')}</div><h2 class="section-heading">功能详情字段 <span class="mini">${data.features.length} 项</span></h2><div class="panel simple-scroll"><table class="simple-table"><thead><tr><th>功能名称</th><th>所属模块</th><th>功能定义 / 比较口径</th><th>优先级</th><th>维护</th></tr></thead><tbody>${data.features.map(f=>`<tr><td>${esc(f.name)}<div class="muted">${esc(f.id)}</div></td><td>${esc(data.modules.find(m=>m.id===f.moduleId)?.name)}</td><td style="max-width:360px">${esc(f.description)}</td><td>${esc(f.priority)}</td><td class="nowrap"><button class="btn" data-edit-feature="${esc(f.id)}">编辑</button> <button class="btn" data-delete-feature="${esc(f.id)}">删除</button></td></tr>`).join('')}</tbody></table></div>`}
function renderImport(){let state=importState;let snapshot=state?.report?.snapshot;let plan=state?.plan;return head('报告导入','将一份独立产品报告转为可审阅的能力更新。先匹配、再核验，确认后写入本地草稿。',`<button class="btn" data-action="template">↓ 下载报告模板</button>`)+`<div class="section-note">当前可解析 JSON、CSV、Markdown / TXT 能力表格，文件在浏览器内处理。PDF / DOCX 与自由文本的 AI 解析为预留能力，尚未连接模型或上传服务器。</div><div class="panel report-area"><div class="report-steps"><div class="on"><b>01</b>上传 / 粘贴报告</div><div class="${state?'on':''}"><b>02</b>结构化解析</div><div class="${plan||snapshot?'on':''}"><b>03</b>匹配与差异预览</div><div><b>04</b>确认更新</div></div><label class="field-label" for="import-product">目标产品 · 同一报告更新一个产品</label><select id="import-product" class="field">${data.products.map(p=>`<option value="${esc(p.id)}" ${p.id===(state?.productId||'qwenwork')?'selected':''}>${esc(p.name)} · ${esc(p.edition)}</option>`).join('')}</select><div class="dropzone" id="dropzone"><div class="upload-icon">↥</div><h3>选择报告文件，或拖放到此处</h3><p>支持 .json / .csv / .md / .txt · 最大 2 MB</p><label class="btn file-label">选择文件<input type="file" id="report-file" accept=".json,.csv,.md,.txt,.pdf,.docx" hidden></label><p>${state?.filename?esc(state.filename):'PDF / Word：预留后续 AI 解析，当前不会上传。'}</p></div><details ${state?.text?'open':''}><summary class="mini" style="cursor:pointer">或粘贴结构化报告文本</summary><label class="field-label" for="report-format">文本格式</label><select id="report-format"><option value="json" ${state?.format==='json'?'selected':''}>JSON</option><option value="md" ${['md','txt'].includes(state?.format)?'selected':''}>Markdown / TXT 表格</option><option value="csv" ${state?.format==='csv'?'selected':''}>CSV</option></select><label class="field-label" for="report-text">报告内容</label><textarea class="field report-text" id="report-text" placeholder='{"productId":"qwenwork","capabilities":[{"module":"认知与知识","feature":"联网与深度研究","status":"有","summary":"能力简介"}]}'>${esc(state?.text||'')}</textarea><button class="btn primary" style="margin-top:12px" data-action="parse-text">解析并预览</button></details>${state?.error?`<div class="error" role="alert">${esc(state.error)}</div>`:''}${snapshot?`<div class="snapshot-warning"><b>检测到完整数据备份</b><p>包含 ${snapshot.products.length} 个产品、${snapshot.modules.length} 个模块、${snapshot.features.length} 个字段。确认恢复将替换当前全部本地看板数据；目标产品选择不适用。可先导出当前草稿。</p><label class="toggle"><input id="review-confirm" type="checkbox">我已检查并同意替换本地数据</label><div class="import-tools"><button class="btn" data-action="export">先导出当前数据</button><button class="btn primary" id="apply-import" disabled>确认恢复备份</button></div></div>`:''}${plan?`<h2 class="section-heading">差异预览 <span class="tag">${plan.length} 条解析记录</span></h2><p class="mini">逐条匹配功能；“新建字段”会影响所有产品的表结构。取消勾选可跳过记录。导入结论标记为未独立核验。</p><div class="import-preview"><table class="simple-table"><thead><tr><th>应用</th><th>报告字段</th><th>匹配到看板字段</th><th>当前 → 报告状态</th><th>报告简介 / 来源</th></tr></thead><tbody>${plan.map((r,i)=>`<tr><td><input class="import-check" data-index="${i}" type="checkbox" checked aria-label="应用第 ${i+1} 条记录"></td><td>${esc(r.feature)}<div class="muted">${esc(r.module||'按匹配字段模块')}</div></td><td><select class="mapping-select" data-index="${i}" aria-label="第 ${i+1} 条目标字段"><option value="new" ${!r.matchedId?'selected':''}>＋ 新建字段</option>${data.features.map(f=>`<option value="${esc(f.id)}" ${r.matchedId===f.id?'selected':''}>${esc(data.modules.find(m=>m.id===f.moduleId).name)} / ${esc(f.name)}</option>`).join('')}</select></td><td><span id="before-${i}">${r.before?badge(r.before):'<span class="tag">新建</span>'}</span> → ${badge(r)}</td><td>${esc(r.summary)}<div class="muted">${r.sourceUrl?`<a href="${esc(safeUrl(r.sourceUrl))}" target="_blank" rel="noopener noreferrer">查看报告引用 ↗</a>`:'未提供来源'} · ${esc(r.checkedAt||'无核验日期')}</div></td></tr>`).join('')}</tbody></table></div><div class="section-note warning" style="margin-top:15px">来源、日期或适用版本不足的条目建议保持“待核实”。上传报告内容仅作为待审阅数据，不作为执行指令，也不会自动改为官方核验结论。</div><label class="toggle"><input id="review-confirm" type="checkbox">我已审阅能力结论、字段映射和适用范围</label><div class="import-tools"><button class="btn" data-action="cancel-import">取消此次导入</button><button class="btn primary" id="apply-import" disabled>确认更新看板数据</button></div>`:''}</div><div class="bottom-grid"><div class="panel method-card"><h3>报告字段约定</h3><p>必填：<b>feature</b>（功能名）、<b>status</b>（有 / 无 / 条件支持 / 待核实）。新增字段还需 <b>module</b>。</p><p>建议：summary、detail、sourceUrl、sourceTitle、checkedAt（YYYY-MM-DD）。JSON 可提供 productId；已有功能可用 featureId 精确匹配。CSV 与 Markdown 支持对应中文表头。</p><button class="link-btn" data-action="sample">载入 Markdown 示例 →</button></div><div class="panel method-card"><h3>后续接入 · 已预留的数据链路</h3><p>PDF / DOCX → 文本 / OCR → AI 能力抽取 → 当前标准 schema → 字段匹配与人工确认 → 数据版本提交。</p><p>解析器只需返回同一 capabilities 结构。数据仓储可替换为带身份校验、权限与版本冲突检测的 API；当前本地修改不会发布给其他访客。</p><a class="link-btn" href="integration.md" target="_blank" rel="noopener">查看接入约定 ↗</a></div></div>`}
function renderHistory(){return head('变更记录','记录当前浏览器内的字段维护、能力编辑和报告更新。可撤销最近一次数据变更。',`<button class="btn" data-action="undo">↶ 撤销最近修改</button><button class="btn danger" data-action="reset-data">恢复初始数据</button>`)+`<div class="section-note">${local?'你正在查看本地草稿。':'当前使用官方资料初核基线。'}记录保存在浏览器，不是企业合规审计日志。完整导出可携带数据与变更历史。</div>${data.history.length?`<div class="panel simple-scroll"><table class="simple-table"><thead><tr><th>时间</th><th>操作</th><th>变更说明</th></tr></thead><tbody>${data.history.map(h=>`<tr><td>${esc(new Date(h.at).toLocaleString(language()==='en'?'en-US':'zh-CN'))}</td><td>${esc(h.action)}</td><td>${esc(h.description)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panel empty"><b>还没有本地修改</b><p>在能力详情中编辑结论、维护字段或导入报告后，这里会保留记录。</p></div>'}`}
function openDialog(selector){let d=$(selector);if(!d.open)d.showModal()}
function closeDetail(){$('#detail-dialog').close();detailState=null}
function openProduct(id){let p=data.products.find(x=>x.id===id);if(!p)return;detailState={type:'product',id};$('#detail-content').innerHTML=`<div class="dialog-head"><div>${logo(p)}<h2>${esc(p.name)}</h2><p>${esc(p.edition)}</p></div><button class="close" data-action="close-detail" aria-label="关闭详情">×</button></div><div class="dialog-body"><span class="tag">${esc(p.category)}</span><p class="detail-body">${esc(p.intro)}</p><h3 class="section-heading">研究范围与边界</h3><p class="detail-body">${esc(p.scope)}</p><div class="detail-grid"><div class="detail-box"><span>文档结论覆盖</span><p>${coverage(p)}% · 不代表功能质量或实测得分</p></div><div class="detail-box"><span>数据记录</span><p>${esc(data.updatedAt)} · ${local?'当前浏览器草稿':'官方资料初核'}</p></div></div><h3 class="section-heading">能力详情</h3><div class="product-detail-list">${data.modules.map(m=>`<h4 class="mini" style="margin:22px 0 5px">${esc(m.name)}</h4>${data.features.filter(f=>f.moduleId===m.id).map(f=>{let c=data.capabilities[id][f.id];return `<button class="cell" data-cell="${esc(id)}|${esc(f.id)}"><strong>${esc(f.name)}</strong>${badge(c)}<p>${esc(c.summary)}</p></button>`}).join('')}`).join('')}</div><h3 class="section-heading">官方资料</h3>${(p.sources||[]).map(id=>sourceMarkup(data.sources[id])).join('')}<div class="dialog-actions"><button class="btn primary" data-action="compare-product" data-id="${esc(id)}">加入对比并打开看板</button></div></div>`;openDialog('#detail-dialog')}
function sourceMarkup(s){if(!s)return '';return `<div class="source-item"><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><small>${esc(s.url)}<br>记录日期：${esc(s.checkedAt||'未注明')}</small></div>`}
function openCell(pid,fid){let p=data.products.find(x=>x.id===pid),f=data.features.find(x=>x.id===fid);if(!p||!f)return;let c=data.capabilities[pid][fid];detailState={type:'cell',pid,fid};$('#detail-content').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${esc(p.name)} / ${esc(data.modules.find(m=>m.id===f.moduleId).name)}</div><h2>${esc(f.name)}</h2><p>${esc(p.edition)}</p></div><button class="close" data-action="close-detail" aria-label="关闭详情">×</button></div><div class="dialog-body">${badge(c)}<h3 class="section-heading">能力简介</h3><p class="detail-body">${esc(c.summary)}</p><h3 class="section-heading">能力详情与适用条件</h3><p class="detail-body">${esc(c.detail)}</p><div class="detail-grid"><div class="detail-box"><span>比较口径</span><p>${esc(f.description)}</p></div><div class="detail-box"><span>适用产品范围</span><p>${esc(p.scope)}</p></div></div><h3 class="section-heading">证据与核验状态</h3><p class="mini">${esc(c.evidence||'待核实')} · ${esc(c.checkedAt||'无核验日期')}${c.reportName?' · 报告：'+esc(c.reportName):''}</p>${c.sourceIds.length?c.sourceIds.map(s=>sourceMarkup(data.sources[s])).join(''):'<div class="section-note warning">当前未关联来源。需补充官方文档、合同或测试证据；不能将未知视为不支持。</div>'}<div class="section-note" style="margin-top:20px">本页未进行统一 PoC。实际效果、可购买范围、配额与服务区域仍须在企业租户验证。</div><div class="dialog-actions"><button class="btn" data-product="${esc(pid)}">产品完整档案</button><button class="btn primary" data-edit-cell="${esc(pid)}|${esc(fid)}">编辑本地结论</button></div></div>`;openDialog('#detail-dialog')}
function editor(title,sub,body,submitLabel='保存到本地'){ $('#editor-content').innerHTML=`<form id="edit-form"><div class="dialog-head"><div><h2>${title}</h2><p>${sub}</p></div><button type="button" class="close" data-action="close-editor" aria-label="关闭编辑">×</button></div><div class="dialog-body">${body}<p class="mini">本地研究数据按原文编辑，界面切换不会改写已保存的研究结论。</p><div id="edit-error"></div><div class="dialog-actions"><button type="button" class="btn" data-action="close-editor">取消</button><button class="btn primary" type="submit">${submitLabel}</button></div></div></form>`;openDialog('#editor-dialog')}
function editorError(message){$('#edit-error').innerHTML=`<div class="error" role="alert">${esc(message)}</div>`}
function input(label,name,value='',type='input'){return `<label class="field-label" for="edit-${name}">${label}</label>${type==='textarea'?`<textarea id="edit-${name}" class="field" name="${name}">${esc(value)}</textarea>`:`<input id="edit-${name}" class="field" name="${name}" value="${esc(value)}" maxlength="${name==='name'?100:1000}">`}`}
function editModule(id){let m=data.modules.find(x=>x.id===id);editor(m?'编辑模块':'新增模块','module 的稳定 ID 在重命名后保持不变。',input('模块名称','name',m?.name));$('#edit-form').onsubmit=e=>{e.preventDefault();let n=new FormData(e.target).get('name').trim();if(!n)return editorError('请填写模块名称');if(data.modules.some(x=>x.name===n&&x.id!==id))return editorError('模块名称已存在');let next=clone(data);if(m)next.modules.find(x=>x.id===id).name=n;else next.modules.push({id:uid('module'),name:n,icon:'▤'});if(save(next,m?'编辑模块':'新增模块',n)){$('#editor-dialog').close();render();toast('模块已保存')}}}
function editFeature(id){let f=data.features.find(x=>x.id===id);if(!data.modules.length){toast('请先新增一个模块');return}editor(f?'编辑功能字段':'新增功能字段','功能定义独立于各产品的支持结论；新增字段默认待核实。',input('功能名称','name',f?.name)+`<label class="field-label" for="edit-module">所属模块</label><select class="field" id="edit-module" name="moduleId">${data.modules.map(m=>`<option value="${esc(m.id)}" ${f?.moduleId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`+input('功能定义 / 比较口径','description',f?.description,'textarea')+`<label class="field-label" for="edit-priority">优先级</label><select class="field" name="priority" id="edit-priority">${['P0','P1','P2'].map(p=>`<option ${f?.priority===p?'selected':''}>${p}</option>`).join('')}</select>`);$('#edit-form').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));v.name=v.name.trim();if(!v.name||!v.description.trim())return editorError('请填写功能名称和比较口径');if(data.features.some(x=>x.name===v.name&&x.moduleId===v.moduleId&&x.id!==id))return editorError('该模块中已有同名功能');let next=clone(data);if(f)Object.assign(next.features.find(x=>x.id===id),v);else{let newId=uid('feature');next.features.push({id:newId,...v});for(let p of next.products)next.capabilities[p.id][newId]={status:'unknown',summary:'待核实',detail:'新增字段，尚未评估。',sourceIds:[],checkedAt:'',evidence:'待核实'}}if(save(next,f?'编辑功能字段':'新增功能字段',v.name)){$('#editor-dialog').close();render();toast('功能字段已保存')}}}
function editCell(pid,fid){let p=data.products.find(x=>x.id===pid),f=data.features.find(x=>x.id===fid),c=data.capabilities[pid][fid],s=data.sources[c.sourceIds[0]];editor('编辑能力结论',esc(p.name)+' / '+esc(f.name)+' · 仅更新当前浏览器草稿',`<label class="field-label" for="edit-status">支持状态</label><select class="field" id="edit-status" name="status">${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${c.status===k?'selected':''}>${v}</option>`).join('')}</select>`+input('能力简介','summary',c.summary)+input('能力详情 / 限制','detail',c.detail,'textarea')+input('主要来源 URL（留空则移除主要来源）','sourceUrl',s?.url)+input('来源标题','sourceTitle',s?.title)+input('核验日期 YYYY-MM-DD','checkedAt',c.checkedAt)+`<p class="mini">其他已关联来源将保留；手动编辑记录标注为“本地人工维护”。</p>`);$('#edit-form').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(!v.summary.trim())return editorError('请填写简介');if(v.sourceUrl&&!safeUrl(v.sourceUrl))return editorError('来源必须是有效 http(s) 地址');if(v.checkedAt&&!/^\d{4}-\d{2}-\d{2}$/.test(v.checkedAt))return editorError('日期格式需为 YYYY-MM-DD');let next=clone(data),ids=c.sourceIds.slice(1);if(v.sourceUrl){let sid=uid('source');next.sources[sid]={url:safeUrl(v.sourceUrl),title:v.sourceTitle||'本地补充来源',checkedAt:v.checkedAt};ids.unshift(sid)}next.capabilities[pid][fid]={...c,status:v.status,summary:v.summary,detail:v.detail||v.summary,sourceIds:ids,checkedAt:v.checkedAt,evidence:'本地人工维护'};if(save(next,'编辑能力结论',p.name+' / '+f.name)){$('#editor-dialog').close();render();openCell(pid,fid);toast('能力结论已更新')}}}
function confirmEdit(title,description,action,buttonLabel='确认'){editor(title,'此操作仅作用于本地草稿；可撤销最近一次修改。',`<p class="detail-body">${esc(description)}</p>`,buttonLabel);$('#edit-form').onsubmit=e=>{e.preventDefault();try{if(action()!==false){$('#editor-dialog').close();render()}}catch(err){editorError(err.message)}}}
function deleteFeature(id){let f=data.features.find(x=>x.id===id);confirmEdit('删除功能字段','将删除“'+f.name+'”及所有产品的对应结论。',()=>{let next=clone(data);next.features=next.features.filter(x=>x.id!==id);for(let p of next.products)delete next.capabilities[p.id][id];return save(next,'删除功能字段',f.name)},'确认删除字段')}
function deleteModule(id){let m=data.modules.find(x=>x.id===id),fs=data.features.filter(f=>f.moduleId===id);if(fs.length){toast('模块仍有 '+fs.length+' 个字段，请先移动或删除字段');return}confirmEdit('删除空模块','将移除空模块“'+m.name+'”。',()=>{let next=clone(data);next.modules=next.modules.filter(x=>x.id!==id);if(moduleId===id)moduleId='all';return save(next,'删除模块',m.name)},'确认删除模块')}
function bindImport(){let file=$('#report-file');file?.addEventListener('change',e=>readFile(e.target.files[0]));let zone=$('#dropzone');for(let ev of ['dragover','dragenter'])zone.addEventListener(ev,e=>{e.preventDefault();zone.classList.add('drag')});zone.addEventListener('dragleave',()=>zone.classList.remove('drag'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag');readFile(e.dataTransfer.files[0])});$('#import-product').addEventListener('change',e=>{if(importState){importState.productId=e.target.value;if(importState.report&&!importState.report.snapshot)try{importState.plan=planImport(data,importState.report,importState.productId);importState.error=''}catch(err){importState.plan=null;importState.error=err.message}render()}});$('#review-confirm')?.addEventListener('change',e=>$('#apply-import').disabled=!e.target.checked);$('#apply-import')?.addEventListener('click',confirmImport);document.querySelectorAll('.mapping-select').forEach(s=>s.addEventListener('change',()=>{let i=Number(s.dataset.index),r=importState.plan[i],f=data.features.find(x=>x.id===s.value);r.matchedId=f?.id||null;r.moduleId=f?.moduleId||data.modules.find(m=>m.name===r.module)?.id||null;r.before=f?data.capabilities[importState.productId][f.id]:null;$('#before-'+i).innerHTML=r.before?badge(r.before):'<span class="tag">新建</span>';$('#review-confirm').checked=false;$('#apply-import').disabled=true}));document.querySelectorAll('.import-check').forEach(c=>c.addEventListener('change',()=>{$('#review-confirm').checked=false;$('#apply-import').disabled=true}))}
async function readFile(file){if(!file)return;if(file.size>2e6){toast('文件超过 2 MB，请拆分后导入');return}let productId=$('#import-product').value;if(/\.(pdf|docx)$/i.test(file.name)){importState={productId,filename:file.name,error:'此格式的 AI 解析已预留接口，当前尚未接入，文件未上传。请转为 JSON / CSV / Markdown 能力表格后导入。'};render();return}try{let text=await file.text();parseInput(text,file.name,productId)}catch(e){importState={productId,filename:file.name,error:e.message};render()}}
function parseInput(text,filename,productId){let format=filename.split('.').pop().toLowerCase();try{let report=canonicalReport(parseReport(text,filename),data);if(report.snapshot)validateDataset(report.snapshot);if(report.productId){if(!data.products.some(p=>p.id===report.productId))throw Error('报告 productId 不在看板中，请修正或去掉此字段后手动选择产品');productId=report.productId}importState={productId,filename,text,format,report,plan:report.snapshot?null:planImport(data,report,productId)};}catch(e){importState={productId,filename,text,format,error:e.message}}render()}
function confirmImport(){if(!$('#review-confirm')?.checked)return;try{if(importState.report.snapshot){let next=clone(importState.report.snapshot);if(!save(next,'恢复数据备份',importState.filename))return;selected=selected.filter(id=>next.products.some(p=>p.id===id));if(!selected.length)selected=next.products.slice(0,4).map(p=>p.id);moduleId='all'}else{let selectedIndices=new Set([...document.querySelectorAll('.import-check:checked')].map(c=>Number(c.dataset.index)));let plan=importState.plan.filter(r=>selectedIndices.has(r.index));if(!plan.length)throw Error('至少勾选一条记录');let keys=new Set();for(let r of plan){let k=r.matchedId||r.module+'|'+r.feature;if(keys.has(k))throw Error('多个报告条目映射到同一功能，请调整映射或跳过重复记录');keys.add(k);if(!r.matchedId&&!r.module)throw Error('新建字段需要模块名称')}let next=applyImport(data,plan,importState.productId,importState.filename);if(!save(next,'导入报告',importState.filename,false))return}importState=null;switchView('compare');toast('已更新本地看板；建议导出完整数据备份')}catch(e){let err=$('.import-apply-error');if(!err){err=document.createElement('div');err.className='error import-apply-error';$('#apply-import').parentElement.before(err)}err.textContent=e.message}}
function toggleProduct(id){selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];try{localStorage.setItem(VIEWKEY,JSON.stringify(selected))}catch{}render()}
const actions={export:exportData,'to-fields':()=>switchView('fields'),'to-import':()=>switchView('import'),all:()=>{selected=data.products.map(p=>p.id);render()},clear:()=>{selected=[];render()},csv:csvExport,'reset-filters':()=>{query='';status='all';moduleId='all';diff=false;render()},'close-detail':closeDetail,'close-editor':()=>$('#editor-dialog').close(),'add-module':()=>editModule(),'add-feature':()=>editFeature(),template:reportTemplate,'cancel-import':()=>{importState=null;render()},'parse-text':()=>parseInput($('#report-text').value,'pasted-report.'+$('#report-format').value,$('#import-product').value),sample:()=>{importState={productId:'qwenwork',format:'md',text:'| 模块 | 功能 | 状态 | 简介 | 来源链接 | 核验日期 |\n| --- | --- | --- | --- | --- | --- |\n| 认知与知识 | 联网与深度研究 | 有 | 示例：请替换为你的报告结论 | https://docs.qwenwork.ai/faq | 2026-10-23 |',filename:'示例 · 尚未解析'};render()},undo:()=>{let raw=localStorage.getItem(UNDO);if(!raw)return toast('没有可撤销的修改');confirmEdit('撤销最近修改','恢复最近一次修改前的本地完整数据。',()=>{let next=JSON.parse(raw);if(!save(next,'撤销修改','恢复上一份本地数据'))return false;localStorage.removeItem(UNDO);selected=selected.filter(id=>next.products.some(p=>p.id===id));moduleId='all';toast('已恢复上一份数据')},'确认撤销')},'reset-data':()=>confirmEdit('恢复初始基线','这将用网站的初始官方资料基线替换当前本地草稿，建议先导出。',()=>{let next=clone(seed);if(!save(next,'恢复初始数据','恢复网站基线'))return false;selected=next.products.slice(0,4).map(p=>p.id);moduleId='all';toast('已恢复初始数据')},'确认恢复')};
document.addEventListener('click',e=>{let b=e.target.closest('button,[data-view]');if(!b)return;let d=b.dataset;if(d.view)switchView(d.view);else if(d.action==='compare-product'){if(!selected.includes(d.id))selected.push(d.id);closeDetail();switchView('compare')}else if(d.action&&actions[d.action])actions[d.action]();else if(d.select)toggleProduct(d.select);else if(d.module){moduleId=d.module;render()}else if(d.preset){selected=({office:['chatgpt','claude','gemini','copilot','qwenwork'],coding:['codex','claude','qoder'],global:['chatgpt','claude','gemini','qwenwork']})[d.preset];render()}else if(d.product)openProduct(d.product);else if(d.cell){let [p,f]=d.cell.split('|');openCell(p,f)}else if(d.editModule)editModule(d.editModule);else if(d.deleteModule)deleteModule(d.deleteModule);else if(d.editFeature)editFeature(d.editFeature);else if(d.deleteFeature)deleteFeature(d.deleteFeature);else if(d.editCell){let [p,f]=d.editCell.split('|');editCell(p,f)}});
document.addEventListener('input',e=>{if(e.target.id==='cap-search'){query=e.target.value;renderMatrix()}});document.addEventListener('change',e=>{if(e.target.id==='status-filter'){status=e.target.value;renderMatrix()}if(e.target.id==='diff-toggle'){diff=e.target.checked;renderMatrix()}if(e.target.id==='compact-toggle'){compact=e.target.checked;renderMatrix()}});
$('#export-btn').onclick=exportData;$('#export-side').onclick=exportData;window.addEventListener('atlas-language-change',()=>{if(view==='compare')renderMatrix()});
window.addEventListener('hashchange',()=>{let v=location.hash.slice(1);if(names[v]&&v!==view){view=v;render()}});
try{let response=await fetch('./data.json');if(!response.ok)throw Error('数据请求失败');seed=await response.json();validateDataset(seed);data=clone(seed);try{let raw=localStorage.getItem(KEY);if(raw){let draft=JSON.parse(raw);validateDataset(draft);data=draft;local=true;if(data.version!==seed.version)storageIssue='本地草稿基于旧版数据。请先导出备份，再到变更记录恢复初始数据以加载新基线。'}let saved=JSON.parse(localStorage.getItem(VIEWKEY)||'null');if(Array.isArray(saved))selected=saved.filter(id=>data.products.some(p=>p.id===id));}catch{storageIssue='本地存储不可用或草稿格式不兼容，已载入网站初始数据。编辑后请检查保存提示。'}selected=selected.filter(id=>data.products.some(p=>p.id===id));view=names[location.hash.slice(1)]?location.hash.slice(1):'compare';render()}catch(e){$('#app').innerHTML=`<div class="error">看板加载失败：${esc(e.message)}。请刷新页面或检查数据文件。</div>`}
